SELECT id,job_desc,executor_handler,trigger_status FROM xxl_job.xxl_job_info WHERE id IN (178,179,186,187);

SELECT job_id,trigger_time,trigger_code,handle_time,handle_code FROM xxl_job.xxl_job_log WHERE job_id=187 AND trigger_time>=DATE_SUB(NOW(),INTERVAL 30 MINUTE) ORDER BY id DESC LIMIT 6;
